head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
scwin.vBzProcsNo = "";
scwin.MSG_TR_DOME = "작업이 정상적으로 처리되었습니다.";
scwin.MSG_TR_FAIL = "처리 중 오류가 발생하였습니다.";
scwin.MGS_NO_UPDT = "저장할 수정내용이 없습니다.";
scwin.fn_GetPar, scwin.fn_SetPar, scwin.strKeyLstBzProcsNo = "", scwin.strKeyIsurCd = "";
scwin.contnId;
scwin.file_flag = "N";
scwin.vScrenID = "ULDSTF07302.xml";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_ShowCalendar = function(o) {
    if ((o != undefined) && (!o.readOnly)) {
        popUpCalendar2(o);
    }
};
scwin.fn_getUserId = function() {
    return js_emp_no;
};


// search function begin
scwin.fn_searchWebRflct = function() {
    var uri = "/konex/PrelmInvstgKonex.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=readWebRflct";
    uri += "&BZ_PROCS_NO=" + scwin.vBzProcsNo;
    dts_ReqInf.DataID = encodeURI(uri);
    dts_ReqInf.reset();
};


// search function end
scwin.fn_save = function(jobType) {
    if ($c.stf.getObjectValue(rdo_InvstgDtlWebDpYn) == 'Y') {
        if (med_INVSTG_DTL_WEB_DP_DD.GetSelClipText(0, 8) == '') {
            $c.win.alert("웹반영여부가 '예'로 체크되어 있으므로 웹반영일을 입력해 주십시오.");
            return;
        }
    }
    if (med_INVSTG_DTL_WEB_DP_DD.GetSelClipText(0, 8) != '') {
        if ($c.stf.getObjectValue(rdo_InvstgDtlWebDpYn) == 'N') {
            $c.win.alert("웹반영일이 입력되어 있으므로 웹반영여부를 '예'로 체크해 주십시오.");
            return;
        }
    }
    var vScrenProcTpCd = SCREN_PROCS_TP_CD_03;
    tr_Save.Action = "/konex/PrelmInvstgKonex.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + vScrenProcTpCd + "&method=modifyWebRflct";
    tr_Save.KeyName = "toinb_dataid4";
    tr_Save.KeyValue = "JSP(I:pInpReqInf=dts_ReqInf)";
    tr_Save.Parameters = "TRS_IDX=U" + ", BZ_PROCS_NO=" + scwin.vBzProcsNo + ", INVSTG_DTL_WEB_DP_YN=" + $c.stf.getObjectValue(rdo_InvstgDtlWebDpYn) + ", INVSTG_DTL_WEB_DP_DD=" + med_INVSTG_DTL_WEB_DP_DD.GetSelClipText(0, 8) + ", LIST_DELIB_SCHDL_DD=" + med_LIST_DELIB_SCHDL_DD.GetSelClipText(0, 8);
    tr_Save.Post();
};
scwin.fn_parentRefresh = function() {
    var fr_fn_list_sync = $c.frame.path("../").fn_list_sync;
    fr_fn_list_sync();
};
scwin.dts_Cmt_OnLoadCompleted = async function(rowcount) {
    if (dts_Cmt.getTotalRow() > 0) {
        fn_setKeyCtrOnUpd(); // 조회직후에는 수정상태
        fn_searchReqInf();
        //fn_fileSearch();
        fn_read();
    } else {
        if (confirm(MSG_NO_COMT)) {
            fn_addNewCmt();
        } else {
            await $c.frame.CloseFrame(); // CloseFrame은 호출자가 있을경우 유효하다.

        }
    }
    /*
    fn_setPanReadOnlyOnLoad(dts_Cmt, pan_Cmt);
    med_ComiteDd.readOnly = true;
    */
};
scwin.dts_Cmt_OnRowPosChanged = function(row) {
    if (dts_Cmt.getTotalRow() > 0) {
        if (dts_Cmt.getCellData(row, "BZ_PROCS_NO") != "") {
            fn_searchReqInf();
        }

        //alert("fn_fileSearch");
        //fn_fileSearch();
        fn_read();
    }
};
scwin.dts_ReqInf_OnLoadCompleted = function(rowcount) {
    med_LIST_DELIB_SCHDL_DD.PutSelClipText(0, 8, dts_ReqInf.getCellData(1, "LIST_DELIB_SCHDL_DD"));
    med_INVSTG_DTL_WEB_DP_DD.PutSelClipText(0, 8, dts_ReqInf.getCellData(1, "INVSTG_DTL_WEB_DP_DD"));
};
scwin.tr_Save_OnFail = function() {
    $c.win.alert(scwin.MSG_TR_FAIL);
};
scwin.tr_Save_OnSuccess = async function() {
    $c.win.alert(scwin.MSG_TR_DOME);
    scwin.fn_parentRefresh();
    await $c.frame.CloseFrame();
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.img_Save_onclick = function() {
    scwin.fn_save("I");
};
scwin.img_SetInvstgDtlWebDpDd_onclick = function() {
    scwin.fn_ShowCalendar(med_INVSTG_DTL_WEB_DP_DD);
};
scwin.img_SetListDelibSchdlDd_onclick = function() {
    scwin.fn_ShowCalendar(med_LIST_DELIB_SCHDL_DD);
};
scwin.gform_onload = function() {
    var arr = new Array();
    var parentWin = $c.frame.path("../");
    scwin.fn_GetPar = parentWin.scwin.fn_GetPar;
    scwin.fn_SetPar = parentWin.scwin.fn_SetPar;
    if (scwin.fn_GetPar != undefined) {
        scwin.fn_GetPar(arr);
    }
    txb_IsurCd.setValue((arr.length >= 1 ? arr[0] : ""));
    txb_CoNm.setValue((arr.length >= 3 ? arr[2] : "")); // 발행기관명도 넘겨받아 컨트롤에 반영해야 한다.

    scwin.vBzProcsNo = parentWin.clickBzProcsNo;
    scwin.fn_searchWebRflct();
};
